// ============================================
// COUNT-UP NUMBER (animates when in view)
// ============================================
function CountUp({ value, suffix = "" }) {
  const ref = useRef(null);
  const [display, setDisplay] = useState(prefersReducedMotion() ? value : 0);

  useEffect(() => {
    if (prefersReducedMotion()) {
      setDisplay(value);
      return;
    }
    const el = ref.current;
    if (!el) return;
    let raf = null;
    const io = new IntersectionObserver(
      ([entry]) => {
        if (!entry.isIntersecting) return;
        io.disconnect();
        const start = performance.now();
        const dur = 1200;
        const tick = (now) => {
          const t = Math.min((now - start) / dur, 1);
          const eased = 1 - Math.pow(1 - t, 3);
          setDisplay(Math.round(eased * value));
          if (t < 1) raf = requestAnimationFrame(tick);
        };
        raf = requestAnimationFrame(tick);
      },
      { threshold: 0.5 }
    );
    io.observe(el);
    return () => {
      io.disconnect();
      if (raf) cancelAnimationFrame(raf);
    };
  }, [value]);

  return (
    <span ref={ref}>
      {display}
      {suffix}
    </span>
  );
}

// ============================================
// LIVE TERMINAL — auto-types agent runs
// ============================================
function AgentTerminal() {
  const [lines, setLines] = useState([]);
  const [current, setCurrent] = useState("");
  const stateRef = useRef({ script: 0, line: 0, char: 0 });
  const timerRef = useRef(null);

  useEffect(() => {
    if (prefersReducedMotion()) {
      setLines(TERMINAL_SCRIPTS[0]);
      return;
    }
    const step = () => {
      const s = stateRef.current;
      const script = TERMINAL_SCRIPTS[s.script];
      const line = script[s.line];

      if (!line) {
        // Script finished — hold, then wipe and move to the next one
        timerRef.current = setTimeout(() => {
          stateRef.current = {
            script: (s.script + 1) % TERMINAL_SCRIPTS.length,
            line: 0,
            char: 0,
          };
          setLines([]);
          setCurrent("");
          step();
        }, 2600);
        return;
      }

      if (s.char < line.t.length) {
        const isCmd = line.cls === "cmd";
        s.char += isCmd ? 1 : 3; // commands "type", output "prints"
        setCurrent(line.t.slice(0, s.char));
        timerRef.current = setTimeout(step, isCmd ? 34 : 12);
      } else {
        setLines((prev) => [...prev, line]);
        setCurrent("");
        s.line += 1;
        s.char = 0;
        timerRef.current = setTimeout(step, line.cls === "cmd" ? 420 : 210);
      }
    };
    timerRef.current = setTimeout(step, 900);
    return () => clearTimeout(timerRef.current);
  }, []);

  const currentCls =
    TERMINAL_SCRIPTS[stateRef.current.script]?.[stateRef.current.line]?.cls ||
    "cmd";

  return (
    <div className="ash-terminal" aria-hidden="true">
      <div className="ash-terminal-bar">
        <span className="ash-tdot ash-tdot-r" />
        <span className="ash-tdot ash-tdot-y" />
        <span className="ash-tdot ash-tdot-g" />
        <span className="ash-terminal-title">laxman@ai-experience-center</span>
        <span className="ash-terminal-live">● live</span>
      </div>
      <div className="ash-terminal-body">
        {lines.map((l, i) => (
          <div key={i} className={`ash-tline ash-tline-${l.cls}`}>
            {l.t}
          </div>
        ))}
        <div className={`ash-tline ash-tline-${currentCls}`}>
          {current}
          <span className="ash-tcursor">▋</span>
        </div>
      </div>
    </div>
  );
}

// ============================================
// AGENT ORCHESTRA — interactive SVG network
// ============================================
/* The task, as a sphere of particles.

   The first build faked this with a dot-grid masked into a ring, which reads
   as a flat sticker the moment it moves. These are real points on a sphere —
   spread by the golden angle so they never band, rotated in 3D and projected
   with perspective, so the near face is bigger and brighter than the far one
   and the silhouette crowds at the rim by itself. Drawn additively, so where
   points overlap the shell lights up. */
function TaskGlobe({ hue, light }) {
  const canvasRef = useRef(null);
  /* The colour changes every couple of seconds as the active agent cycles;
     keeping it in a ref means the loop is never torn down to pick it up. */
  const hueRef = useRef(hue);
  const lightRef = useRef(light);
  hueRef.current = hue;
  lightRef.current = light;

  const points = useMemo(() => {
    const N = 1150;
    const golden = Math.PI * (3 - Math.sqrt(5));
    const out = [];
    for (let i = 0; i < N; i++) {
      const y = 1 - (i / (N - 1)) * 2;
      const ring = Math.sqrt(Math.max(0, 1 - y * y));
      const th = golden * i;
      out.push({
        x: Math.cos(th) * ring,
        y,
        z: Math.sin(th) * ring,
        /* A fixed per-point mix between the agent's colour and plain light,
           plus a few warm ones low on the sphere. */
        t: (i * 2654435761) % 1000 / 1000,
        warm: y < -0.35 && i % 11 === 0,
      });
    }
    return out;
  }, []);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return undefined;
    const ctx = canvas.getContext("2d");
    if (!ctx) return undefined;

    const reduced = prefersReducedMotion();
    let raf = 0;
    let angle = 0.6;
    let size = { w: 0, h: 0 };

    const setSize = () => {
      const r = canvas.getBoundingClientRect();
      const w = Math.round(r.width);
      const h = Math.round(r.height);
      if (!w || !h) return;
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.round(w * dpr);
      canvas.height = Math.round(h * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      size = { w, h };
    };

    const rgb = (hex) => {
      const m = /^#?([0-9a-f]{6})$/i.exec(String(hex || "").trim());
      if (!m) return { r: 139, g: 92, b: 246 };
      const n = parseInt(m[1], 16);
      return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
    };

    const draw = () => {
      const { w, h } = size;
      if (!w || !h) return;
      const cx = w / 2;
      const cy = h / 2;
      const R = Math.min(w, h) * 0.46;
      const c = rgb(hueRef.current);
      const dark = !lightRef.current;

      ctx.clearRect(0, 0, w, h);
      ctx.globalCompositeOperation = dark ? "lighter" : "source-over";

      /* Tilted a little towards the viewer, so the pole is visible and the
         thing reads as a globe rather than a spinning disc. */
      const tilt = 0.42;
      const ct = Math.cos(tilt);
      const st = Math.sin(tilt);
      const ca = Math.cos(angle);
      const sa = Math.sin(angle);

      for (const p of points) {
        const x1 = p.x * ca - p.z * sa;
        const z1 = p.x * sa + p.z * ca;
        const y2 = p.y * ct - z1 * st;
        const z2 = p.y * st + z1 * ct;

        /* Perspective: 1 at the near pole, ~0.72 at the far one. */
        const persp = 2.9 / (2.9 + z2);
        const sx = cx + x1 * R * persp;
        const sy = cy + y2 * R * persp;

        const depth = (z2 + 1) / 2; /* 0 far, 1 near */
        const alpha = (dark ? 0.09 : 0.13) + depth * (dark ? 0.86 : 0.62);
        const rad = (0.62 + depth * 1.35) * persp;

        let cr;
        let cg;
        let cb;
        if (p.warm) {
          cr = 244;
          cg = 164;
          cb = 96;
        } else if (p.t > 0.62) {
          /* The light half of the population: white in the dark theme, ink in
             the light one. */
          cr = dark ? 226 : 40;
          cg = dark ? 232 : 44;
          cb = dark ? 245 : 70;
        } else {
          cr = c.r;
          cg = c.g;
          cb = c.b;
        }

        /* Points on the near face get a second, much larger and fainter
           pass. Drawn additively that reads as bloom coming off the front of
           the sphere — the cheap way to light something without a filter. */
        if (dark && depth > 0.68) {
          ctx.beginPath();
          ctx.arc(sx, sy, rad * 3.1, 0, Math.PI * 2);
          ctx.fillStyle = `rgba(${cr},${cg},${cb},${(
            (depth - 0.68) * 0.12
          ).toFixed(3)})`;
          ctx.fill();
        }

        ctx.beginPath();
        ctx.arc(sx, sy, rad, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(${cr},${cg},${cb},${alpha.toFixed(3)})`;
        ctx.fill();
      }

      /* The rim. A stroked circle at the silhouette, blurred into a halo —
         this is what makes it glow rather than just sparkle. */
      if (dark) {
        ctx.beginPath();
        ctx.arc(cx, cy, R * 1.01, 0, Math.PI * 2);
        /* Faint enough to read as the light coming off the silhouette rather
           than as a circle someone drew. */
        ctx.strokeStyle = `rgba(${c.r},${c.g},${c.b},0.1)`;
        ctx.lineWidth = 1.5;
        ctx.shadowBlur = 30;
        ctx.shadowColor = `rgba(${c.r},${c.g},${c.b},0.75)`;
        ctx.stroke();
        ctx.stroke();
        ctx.shadowBlur = 0;
      }

      ctx.globalCompositeOperation = "source-over";
    };

    setSize();
    draw();

    let ro = null;
    if (typeof ResizeObserver !== "undefined") {
      ro = new ResizeObserver(() => {
        setSize();
        draw();
      });
      ro.observe(canvas);
    }

    if (reduced) {
      return () => {
        if (ro) ro.disconnect();
      };
    }

    const tick = () => {
      angle += 0.0022;
      draw();
      raf = requestAnimationFrame(tick);
    };

    /* Off screen it stops outright — it sits a long way up a long page. */
    let io = null;
    const start = () => {
      if (!raf) raf = requestAnimationFrame(tick);
    };
    const stop = () => {
      if (raf) {
        cancelAnimationFrame(raf);
        raf = 0;
      }
    };
    if (typeof IntersectionObserver !== "undefined") {
      io = new IntersectionObserver(
        ([e]) => (e.isIntersecting ? start() : stop()),
        { rootMargin: "160px" }
      );
      io.observe(canvas);
    } else {
      start();
    }

    return () => {
      stop();
      if (ro) ro.disconnect();
      if (io) io.disconnect();
    };
  }, [points]);

  return <canvas ref={canvasRef} className="ash-orbit-canvas" aria-hidden="true" />;
}

function AgentOrchestra({ light = false }) {
  const [active, setActive] = useState(0);
  // Hover and keyboard focus both hold the diagram on one agent, so tabbing
  // through the nodes behaves the same as pointing at them.
  const [held, setHeld] = useState(null);
  const idx = held !== null ? held : active;
  const reduced = prefersReducedMotion();

  useEffect(() => {
    if (reduced || held !== null) return;
    const id = setInterval(
      () => setActive((a) => (a + 1) % AGENTS.length),
      2600
    );
    return () => clearInterval(id);
  }, [held, reduced]);

  /* Three arcs, two agents each. Everything turns around a point on the bottom
     edge of the stage, which is what crops the rings into arcs and puts the
     task on the horizon rather than in a wheel.

     The agents sway along their arc rather than circling it: a full rotation
     spends half its time below the horizon, and an agent you cannot see is an
     agent you cannot hover, click or count. Angles are measured from 3
     o'clock, negative being up, and none is shallower than 40° so the sway
     can never dip one under. */
  const orbits = useMemo(
    () =>
      AGENTS.map((agent, i) => ({
        agent,
        /* Steep angles on the short arcs, shallow ones on the long arcs —
           that way every chip, sway included, stays inside the stage instead
           of sailing off the top or the sides of it. The two on a given arc
           are kept 60° apart or more, so their swings never bring them into
           the same place. */
        ring: [1, 2, 3, 3, 2, 1][i],
        angle: [-60, -50, -35, -145, -130, -120][i],
        /* Negative delay starts each one part-way through its swing, so six
           chips never drift in formation. */
        lag: [0, 0.31, 0.62, 0.17, 0.48, 0.79][i],
      })),
    []
  );

  return (
    <div
      className="ash-orchestra"
      data-ash-reveal
      style={{ "--ash-active": AGENTS[idx].hue }}
    >
      <div
        className={`ash-orbit${reduced ? " is-still" : ""}`}
        role="group"
        aria-label="Six AI agents orbiting one task"
      >
        <span className="ash-orbit-track is-r1" aria-hidden="true" />
        <span className="ash-orbit-track is-r2" aria-hidden="true" />
        <span className="ash-orbit-track is-r3" aria-hidden="true" />

        {/* The task: a shell of particles on the horizon, taking the colour of
            whichever agent is contributing. */}
        <div className="ash-orbit-globe" aria-hidden="true">
          <span className="ash-orbit-glow" />
          <TaskGlobe hue={AGENTS[idx].hue} light={light} />
        </div>

        <p className="ash-orbit-badge">
          <em aria-hidden="true">⚡</em>
          your task
        </p>

        {orbits.map(({ agent, ring, angle, lag }, i) => (
          <button
            key={agent.name}
            type="button"
            className={`ash-orbit-chip is-r${ring}${i === idx ? " is-on" : ""}`}
            style={{
              "--a": `${angle}deg`,
              "--lag": lag,
              "--ash-hue": agent.hue,
            }}
            data-cursor={agent.name}
            aria-label={`${agent.name} — ${agent.blurb}`}
            aria-pressed={i === idx}
            onMouseEnter={() => setHeld(i)}
            onMouseLeave={() => setHeld(null)}
            onFocus={() => setHeld(i)}
            onBlur={() => setHeld(null)}
            onClick={() => setActive(i)}
          >
            <span className="ash-orbit-icon" aria-hidden="true">
              {agent.icon}
            </span>
            <span className="ash-orbit-name" aria-hidden="true">
              {agent.name}
            </span>
          </button>
        ))}
      </div>

      <div className="ash-orchestra-caption" aria-live="polite">
        <span className="ash-orchestra-icon">{AGENTS[idx].icon}</span>
        <div>
          <strong>{AGENTS[idx].name}</strong>
          <p>{AGENTS[idx].blurb}</p>
        </div>
      </div>
    </div>
  );
}

// ============================================
// TILT CARD — 3D hover tilt (fine pointers)
// ============================================
// matchMedia allocates a MediaQueryList on every call and the tilt handler
// runs on every mousemove across fifteen cards, so the answer is cached.
let tiltAllowed = null;
const canTilt = () => {
  if (tiltAllowed === null) {
    tiltAllowed = isFinePointer() && !prefersReducedMotion();
  }
  return tiltAllowed;
};

// ============================================
// MAGNIFY — a lens that enlarges the heading under the cursor
// ============================================
// A real magnifier rather than a hover-scale: a second copy of the text is
// scaled up and clipped to a circle that tracks the pointer, so the words
// under the glass grow while the rest of the line stays put.
//
// Three details make it work:
//   • The clip lives on an untransformed wrapper and the scale on its child.
//     Both on one element and the circle would be scaled along with the text.
//   • transform-origin is set to the cursor position, which is what pins the
//     point under the glass so it magnifies in place instead of sliding away.
//   • The base copy is masked out inside the circle. Without that hole the
//     original text reads straight through the enlarged one and the heading
//     looks doubled — which is also what a real lens does: it occludes.
//
// Position is published as two CSS variables and the clip, the mask, the
// origin and the ring all derive from them, so a move costs two property
// writes rather than a style write per element.
//
// The copy is mounted only while hovering, so the prerendered HTML a crawler
// sees contains each heading exactly once.
function Magnify({ children, zoom = 1.55, radius = 88 }) {
  const [on, setOn] = useState(false);
  const wrapRef = useRef(null);
  const rafRef = useRef(null);

  const place = useCallback((x, y) => {
    if (rafRef.current) cancelAnimationFrame(rafRef.current);
    rafRef.current = requestAnimationFrame(() => {
      rafRef.current = null;
      const wrap = wrapRef.current;
      if (!wrap) return;
      wrap.style.setProperty("--mag-x", `${x}px`);
      wrap.style.setProperty("--mag-y", `${y}px`);
    });
  }, []);

  const onEnter = useCallback(
    (e) => {
      if (!canTilt()) return;
      const r = e.currentTarget.getBoundingClientRect();
      place(e.clientX - r.left, e.clientY - r.top);
      setOn(true);
    },
    [place]
  );

  const onMove = useCallback(
    (e) => {
      if (!canTilt()) return;
      const r = e.currentTarget.getBoundingClientRect();
      place(e.clientX - r.left, e.clientY - r.top);
    },
    [place]
  );

  const onLeave = useCallback(() => {
    if (rafRef.current) cancelAnimationFrame(rafRef.current);
    rafRef.current = null;
    setOn(false);
  }, []);

  useEffect(
    () => () => {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
    },
    []
  );

  return (
    <span
      className={`ash-mag ${on ? "ash-mag-on" : ""}`}
      ref={wrapRef}
      style={{ "--mag-r": `${radius}px`, "--mag-zoom": zoom }}
      onMouseEnter={onEnter}
      onMouseMove={onMove}
      onMouseLeave={onLeave}
    >
      <span className="ash-mag-base">{children}</span>
      {on && (
        <>
          <span className="ash-mag-lens" aria-hidden="true">
            <span className="ash-mag-inner">{children}</span>
          </span>
          <span className="ash-mag-ring" aria-hidden="true" />
        </>
      )}
    </span>
  );
}

/* `flat` keeps the cursor-tracked sheen but drops the 3D rotation — the tilt
   was the loudest thing about these cards, and next to the tool cards above
   (which lift, not wobble) it read as a different page. */
function TiltCard({ children, className, style, flat = false, ...rest }) {
  const ref = useRef(null);
  const rafRef = useRef(null);

  const onMove = useCallback(
    (e) => {
      if (!canTilt()) return;
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      rafRef.current = requestAnimationFrame(() => {
        const el = ref.current;
        if (!el) return;
        const r = el.getBoundingClientRect();
        const x = e.clientX - r.left;
        const y = e.clientY - r.top;
        if (flat) {
          el.style.transform = "translateY(-4px)";
        } else {
          const rx = ((r.height / 2 - y) / r.height) * 8;
          const ry = ((x - r.width / 2) / r.width) * 8;
          el.style.transform = `perspective(800px) rotateX(${rx}deg) rotateY(${ry}deg) translateY(-6px)`;
        }
        el.style.setProperty("--mx", `${x}px`);
        el.style.setProperty("--my", `${y}px`);
      });
    },
    [flat]
  );

  const onLeave = useCallback(() => {
    if (rafRef.current) cancelAnimationFrame(rafRef.current);
    if (ref.current) ref.current.style.transform = "";
  }, []);

  return (
    <article
      ref={ref}
      className={className}
      style={style}
      onMouseMove={onMove}
      onMouseLeave={onLeave}
      {...rest}
    >
      {children}
    </article>
  );
}

