import React from "react";
import { ArrowRight, Lock } from "lucide-react";

import "./GradientCard.css";

/* A card that leads with one graphic and one sentence instead of a stack of
   chips, bullets and glows. Ported from the shadcn/Tailwind original to this
   codebase's stack — plain JS, a stylesheet instead of utility classes and
   cva, CSS transitions instead of framer-motion (the pages using this run
   nine of these at once and already keep their motion on the compositor).

   The named gradients from the original are kept, and a `hue` pair is
   accepted too, so a page that already gives each item its own colour can
   hand that colour straight over. */

const GRADIENTS = {
  orange: ["#f59e0b", "#fb923c"],
  gray: ["#94a3b8", "#cbd5e1"],
  purple: ["#8b5cf6", "#6366f1"],
  green: ["#10b981", "#14b8a6"],
};

export default function GradientCard({
  badgeText,
  badgeColor,
  title,
  description,
  /* A quiet line between title and description — where the thing lives, what
     it costs, how long it takes. Optional. */
  meta,
  /* Anything else the card has to carry. Kept last in the reading order and
     styled by the host page, so this component never owns a bullet list. */
  children,
  ctaText,
  ctaHref,
  onCtaClick,
  /* Extra attributes for the CTA itself — a data-cursor label, an aria
     description — without having to spread them over the whole card. */
  ctaProps,
  /* Shows a padlock ahead of the label — for a CTA that leads to a sign-in. */
  ctaLocked = false,
  imageUrl,
  gradient = "gray",
  hue,
  className = "",
  style,
  ...rest
}) {
  const pair = hue || GRADIENTS[gradient] || GRADIENTS.gray;
  const [a, b] = pair;

  const ctaInner = (
    <>
      {ctaLocked && <Lock className="gcard-cta-lock" aria-hidden="true" />}
      {ctaText}
      <ArrowRight className="gcard-cta-arrow" aria-hidden="true" />
    </>
  );

  return (
    <article
      className={`gcard${className ? ` ${className}` : ""}`}
      style={{ "--gc-a": a, "--gc-b": b, ...style }}
      {...rest}
    >
      {/* Decoration, so it is hidden from assistive tech rather than described
          — the title already says what the card is. */}
      {imageUrl && (
        <img
          className="gcard-art"
          src={imageUrl}
          alt=""
          aria-hidden="true"
          loading="lazy"
          decoding="async"
        />
      )}

      <div className="gcard-body">
        {badgeText && (
          <span className="gcard-badge">
            <i
              className="gcard-badge-dot"
              style={badgeColor ? { background: badgeColor } : undefined}
              aria-hidden="true"
            />
            {badgeText}
          </span>
        )}

        <h3 className="gcard-title">{title}</h3>
        {meta && <p className="gcard-meta">{meta}</p>}
        {description && <p className="gcard-desc">{description}</p>}

        {children}

        {ctaText &&
          (ctaHref ? (
            <a className="gcard-cta" href={ctaHref} {...ctaProps}>
              {ctaInner}
            </a>
          ) : (
            <button
              type="button"
              className="gcard-cta"
              onClick={onCtaClick}
              {...ctaProps}
            >
              {ctaInner}
            </button>
          ))}
      </div>
    </article>
  );
}

export { GRADIENTS };
